  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
  transition: transform var(--transition-med);
}

.diff-card:hover { transform: translateY(-2px); }

.diff-card .diff-icon {
  font-size: 40px;
  margin-bottom: var(--space-md);
}

.diff-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.diff-card p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}

/* --- Brand Collab --- */
.brand-collab {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-3xl) var(--space-lg);
}

.brand-collab h2 {
  font-size: clamp(24px, 3vw, 40px);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-sm);
}

.brand-collab p {
  font-size: 18px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.brand-collab-items {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
}

.brand-collab-item {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-lg);
  text-align: center;
  width: 180px;
}

.brand-collab-item .item-icon { font-size: 48px; margin-bottom: var(--space-sm); }
.brand-collab-item h4 { font-size: 14px; font-weight: 600; }

/* --- Quick Links --- */
.quick-links {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
  padding: var(--space-2xl) var(--space-lg);
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-lg);
  border: 1px solid var(--color-border);
  border-radius: 20px;
  font-size: 14px;
  color: var(--color-primary-hex);
  text-decoration: none;
  transition: all var(--transition-fast);
}

.quick-link:hover {
  background: var(--color-bg-light-hex);
  text-decoration: none;
}

/* --- Category Sticky Nav --- */
.category-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
}

.category-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--space-xl);
  padding: var(--space-sm) var(--space-lg);
  overflow-x: auto;
  scrollbar-width: none;
}

.category-nav-inner::-webkit-scrollbar { display: none; }

.category-nav a {
  font-size: 13px;
  font-weight: 400;
  color: var(--color-secondary-text-hex);
  text-decoration: none;
  white-space: nowrap;
  padding: var(--space-xs) 0;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
}

.category-nav a:hover {
  color: var(--color-primary-hex);
  text-decoration: none;
}

.category-nav a.active {
  color: var(--color-primary-hex);
  border-bottom-color: var(--color-primary-hex);
}

/* --- Shopping Guides --- */
.guide-list {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.guide-item {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
}

.guide-item .guide-icon { font-size: 40px; margin-bottom: var(--space-md); }

.guide-item h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.guide-item p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}

/* --- Ways to Save --- */
.save-list {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-md);
}

.save-item {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
}

.save-item .save-icon { font-size: 36px; margin-bottom: var(--space-md); }

.save-item h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.save-item p {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
}

/* --- Setup Support --- */
.setup-support {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg);
}

.setup-support h3 {
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.setup-support p {
  font-size: 16px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

/* --- Product Experience --- */
.product-experience {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg);
}

.product-experience h3 {
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.product-experience p {
  font-size: 16px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-md);
}

/* --- Special Stores --- */
.special-stores-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--space-md);
}

.special-store-card {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  text-align: center;
  transition: transform var(--transition-med);
}

.special-store-card:hover { transform: translateY(-2px); }

.special-store-card .store-icon { font-size: 36px; margin-bottom: var(--space-md); }

.special-store-card h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.special-store-card p {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
}

/* --- Footer --- */
.site-footer {
  background: var(--color-bg-light-hex);
  padding: var(--space-2xl) var(--space-lg) var(--space-lg);
  border-top: 1px solid var(--color-border);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-legal {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  line-height: 1.6;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-lg);
  border-bottom: 1px solid var(--color-border);
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-2xl);
  margin-bottom: var(--space-2xl);
}

.footer-col h4 {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-primary-hex);
  margin-bottom: var(--space-sm);
  cursor: default;
}

.footer-col ul li {
  margin-bottom: 4px;
}

.footer-col ul li a {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  transition: color var(--transition-fast);
}

.footer-col ul li a:hover {
  color: var(--color-primary-hex);
  text-decoration: none;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-md);
  border-top: 1px solid var(--color-border);
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  flex-wrap: wrap;
  gap: var(--space-sm);
}

/* --- Footer Accordion (Mobile) --- */
@media (max-width: 768px) {
  .footer-columns {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid var(--color-border);
  }

  .footer-col h4 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--space-md) 0;
    cursor: pointer;
    user-select: none;
  }

  .footer-col h4::after {
    content: '+';
    font-size: 16px;
    font-weight: 400;
    transition: transform var(--transition-fast);
  }

  .footer-col.open h4::after {
    content: '−';
  }

  .footer-col ul {
    display: none;
    padding-bottom: var(--space-md);
  }

  .footer-col.open ul {
    display: block;
  }
}

/* --- Responsive --- */
@media (max-width: 768px) {
  .product-grid {
    grid-template-columns: 1fr;
  }

  .product-tile {
    min-height: 340px;
  }

  .global-nav .nav-links {
    gap: var(--space-md);
  }

  .global-nav .nav-links a {
    font-size: 11px;
  }

  .product-bar-inner {
    justify-content: flex-start;
    gap: var(--space-lg);
  }

  .carousel-arrow {
    display: none;
  }

  .carousel-track {
    padding-left: var(--space-md);
    padding-right: var(--space-md);
  }

  .product-card {
    flex: 0 0 240px;
  }

  .help-cards, .diff-cards, .guide-list, .save-list, .special-stores-grid {
    grid-template-columns: 1fr;
  }

  .entertainment-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .brand-collab-items {
    justify-content: flex-start;
    overflow-x: auto;
    flex-wrap: nowrap;
  }

  .quick-links {
    justify-content: flex-start;
    overflow-x: auto;
    flex-wrap: nowrap;
  }
}

@media (max-width: 480px) {
  .entertainment-cards {
    grid-template-columns: 1fr;
  }

  .page-hero {
    padding: var(--space-2xl) var(--space-md) var(--space-xl);
  }

  .section {
    padding: var(--space-2xl) var(--space-md);
  }
}

/* --- Utility --- */
.text-center { text-align: center; }
.mt-lg { margin-top: var(--space-lg); }
.mb-lg { margin-bottom: var(--space-lg); }

/* --- Savings Carousel Cards --- */
.savings-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  transition: transform var(--transition-med);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg) var(--space-lg);
}

.savings-card:hover { transform: translateY(-2px); }

.savings-card .savings-icon {
  font-size: 48px;
  margin-bottom: var(--space-md);
}

.savings-card h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.savings-card p {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  line-height: 1.5;
}

/* --- Experience Section --- */
.experience-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-md);
}

.experience-card {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  text-align: center;
}

.experience-card .exp-icon { font-size: 40px; margin-bottom: var(--space-md); }

.experience-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.experience-card p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}
