/* ============================================
   Orchard — Design System & Shared Styles
   ============================================ */

/* --- OKLCH Color Tokens --- */
:root {
  --color-primary: oklch(20% 0.02 265);
  --color-primary-hex: #1d1d1f;
  --color-secondary-text: oklch(52% 0.01 265);
  --color-secondary-text-hex: #6e6e73;
  --color-bg-light: oklch(97% 0.005 265);
  --color-bg-light-hex: #f5f5f7;
  --color-bg-white: #ffffff;
  --color-blue: oklch(50% 0.19 265);
  --color-blue-hex: #0066cc;
  --color-blue-hover: #004499;
  --color-border: #d2d2d7;
  --color-badge: #bf4800;
  --color-tile-bg-1: #fbfbfd;
  --color-tile-bg-2: #f0f0f5;

  /* Typography */
  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 48px;

  /* Cards */
  --card-radius: 18px;
  --card-shadow: 0 2px 12px rgba(0,0,0,0.08);

  /* Carousel */
  --carousel-card-width: 280px;
  --carousel-gap: 16px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-med: 250ms ease;
  --transition-slow: 400ms ease;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-stack);
  color: var(--color-primary-hex);
  background: var(--color-bg-white);
  line-height: 1.5;
  overflow-x: hidden;
}

a { color: var(--color-blue-hex); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--color-blue-hover); text-decoration: underline; }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

ul, ol { list-style: none; }

/* --- Top Navigation (Slim Nav) --- */
.global-nav {
  background: rgba(29,29,31,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--nav-height);
}

.global-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 var(--space-lg);
}

.global-nav .logo {
  color: #f5f5f7;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
}

.global-nav .nav-links {
  display: flex;
  gap: var(--space-xl);
  align-items: center;
}

.global-nav .nav-links a {
  color: rgba(245,245,247,0.85);
  font-size: 12px;
  font-weight: 400;
  text-decoration: none;
  transition: color var(--transition-fast);
  letter-spacing: 0;
}

.global-nav .nav-links a:hover {
  color: #fff;
  text-decoration: none;
}

/* --- Ribbon Banner --- */
.ribbon-banner {
  background: var(--color-bg-light-hex);
  text-align: center;
  padding: var(--space-sm) var(--space-md);
  font-size: 14px;
  color: var(--color-primary-hex);
  border-bottom: 1px solid var(--color-border);
}

.ribbon-banner a {
  color: var(--color-blue-hex);
  white-space: nowrap;
}

/* --- Page Hero --- */
.page-hero {
  text-align: center;
  padding: var(--space-4xl) var(--space-lg) var(--space-2xl);
}

.page-hero h1 {
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.08;
  margin-bottom: var(--space-sm);
}

.page-hero p {
  font-size: clamp(18px, 2.5vw, 24px);
  font-weight: 400;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.hero-ctas {
  display: flex;
  gap: var(--space-lg);
  justify-content: center;
  flex-wrap: wrap;
}

.hero-ctas a {
  font-size: 17px;
  font-weight: 400;
}

/* --- Section --- */
.section {
  padding: var(--space-3xl) var(--space-lg);
}

.section-light {
  background: var(--color-bg-light-hex);
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.section-header h2 {
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: var(--space-sm);
}

.section-header p {
  font-size: clamp(16px, 2vw, 21px);
  color: var(--color-secondary-text-hex);
  font-weight: 400;
}

.section-header .promo {
  font-size: 14px;
  color: var(--color-secondary-text-hex);
  margin-top: var(--space-xs);
}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  gap: var(--carousel-gap);
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: var(--space-sm) 0 var(--space-md);
  scrollbar-width: none;
}

.carousel-track::-webkit-scrollbar { display: none; }

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.85);
  border: 1px solid var(--color-border);
  box-shadow: 0 1px 4px rgba(0,0,0,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: background var(--transition-fast), box-shadow var(--transition-fast);
  cursor: pointer;
}

.carousel-arrow:hover {
  background: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}

.carousel-arrow svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: var(--color-primary-hex);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.carousel-arrow.prev { left: -18px; }
.carousel-arrow.next { right: -18px; }

.carousel-arrow:disabled {
  opacity: 0.3;
  cursor: default;
}

/* --- Product Card (Carousel) --- */
.product-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  transition: transform var(--transition-med), box-shadow var(--transition-med);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 20px rgba(0,0,0,0.12);
}

.product-card .card-img {
  width: 100%;
  height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}

.product-card .card-img .badge {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--color-badge);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.product-card .card-img .product-icon {
  font-size: 72px;
  opacity: 0.9;
}

.product-card .card-body {
  padding: var(--space-md);
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-card .card-body h3 {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
  margin-bottom: 4px;
}

.product-card .card-body .tagline {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-sm);
  line-height: 1.4;
}

.product-card .card-body .price {
  font-size: 14px;
  font-weight: 600;
  margin-top: auto;
}

.product-card .card-body .monthly {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  font-weight: 400;
}

.product-card .card-body .card-links {
  display: flex;
  gap: var(--space-md);
  margin-top: var(--space-sm);
}

.product-card .card-body .card-links a {
  font-size: 13px;
}

.product-card .note {
  font-size: 11px;
  color: var(--color-secondary-text-hex);
  margin-top: 4px;
}

/* Product image placeholder styles */
.img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80px;
}

.img-placeholder.phone { background: linear-gradient(135deg, #e8e8ed 0%, #d2d2d7 100%); }
.img-placeholder.laptop { background: linear-gradient(135deg, #e8edf0 0%, #c8d0d8 100%); }
.img-placeholder.tablet { background: linear-gradient(135deg, #ece8f0 0%, #d8d0e0 100%); }
.img-placeholder.headphones { background: linear-gradient(135deg, #f0ece8 0%, #e0d8d0 100%); }
.img-placeholder.watch { background: linear-gradient(135deg, #e8f0ec 0%, #d0e0d8 100%); }
.img-placeholder.speaker { background: linear-gradient(135deg, #f0f0e8 0%, #e0e0d0 100%); }
.img-placeholder.accessory { background: linear-gradient(135deg, #f5f0f0 0%, #e8e0e0 100%); }
.img-placeholder.earbuds { background: linear-gradient(135deg, #f0e8f0 0%, #e0d8e0 100%); }

/* --- Product Grid (Homepage) --- */
.product-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
  padding: 0 var(--space-lg);
}

.product-tile {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  overflow: hidden;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg) var(--space-lg);
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 400px;
}

.product-tile .tile-img {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 100px;
  margin-bottom: var(--space-lg);
}

.product-tile h3 {
  font-size: clamp(24px, 3vw, 32px);
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: var(--space-xs);
}

.product-tile .tile-tagline {
  font-size: clamp(16px, 2vw, 19px);
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.product-tile .tile-ctas {
  display: flex;
  gap: var(--space-lg);
  justify-content: center;
}

.product-tile .tile-ctas a {
  font-size: 15px;
}

.tile-tradein {
  background: linear-gradient(135deg, #1d1d1f 0%, #3a3a3c 100%);
  color: #f5f5f7;
}

.tile-tradein h3 { color: #f5f5f7; }
.tile-tradein .tile-tagline { color: rgba(245,245,247,0.8); }

/* --- Entertainment Tabs --- */
.entertainment-section {
  max-width: var(--max-width);
  margin: 0 auto;
}

.tab-nav {
  display: flex;
  gap: var(--space-sm);
  justify-content: center;
  margin-bottom: var(--space-2xl);
  flex-wrap: wrap;
}

.tab-nav button {
  padding: var(--space-sm) var(--space-lg);
  font-size: 15px;
  font-weight: 500;
  border-radius: 20px;
  color: var(--color-primary-hex);
  background: var(--color-bg-light-hex);
  transition: all var(--transition-fast);
}

.tab-nav button:hover {
  background: var(--color-border);
}

.tab-nav button.active {
  background: var(--color-primary-hex);
  color: #fff;
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

.entertainment-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-md);
}

.entertainment-card {
  border-radius: var(--card-radius);
  overflow: hidden;
  background: var(--color-bg-white);
  box-shadow: var(--card-shadow);
  transition: transform var(--transition-med);
}

.entertainment-card:hover {
  transform: translateY(-2px);
}

.entertainment-card .card-visual {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 56px;
}

.entertainment-card .card-info {
  padding: var(--space-md);
}

.entertainment-card .card-info h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}

.entertainment-card .card-info .subtitle {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-sm);
}

.entertainment-card .card-info a {
  font-size: 13px;
}

/* --- Product Icon Bar --- */
.product-bar {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: var(--space-lg);
  overflow-x: auto;
  scrollbar-width: none;
}

.product-bar::-webkit-scrollbar { display: none; }

.product-bar-inner {
  display: flex;
  gap: var(--space-xl);
  justify-content: center;
  min-width: max-content;
}

.product-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-xs);
  text-decoration: none;
  color: var(--color-primary-hex);
  transition: color var(--transition-fast);
  flex-shrink: 0;
}

.product-bar-item:hover { color: var(--color-blue-hex); text-decoration: none; }

.product-bar-item .bar-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: var(--color-bg-light-hex);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  transition: background var(--transition-fast);
}

.product-bar-item:hover .bar-icon {
  background: var(--color-border);
}

.product-bar-item span {
  font-size: 11px;
  font-weight: 500;
  text-align: center;
}

/* --- Help Cards --- */
.help-cards {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.help-card {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
  transition: transform var(--transition-med);
}

.help-card:hover { transform: translateY(-2px); }

.help-card .help-icon {
  font-size: 48px;
  margin-bottom: var(--space-md);
}

.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.help-card p {
  font-size: 14px;
  color: var(--color-secondary-text-hex);
  line-height: 1.5;
}

/* --- Difference Cards --- */
.diff-cards {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-md);
}

.diff-card {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
  transition: transform var(--transition-med);
}

.diff-card:hover { transform: translateY(-2px); }

.diff-card .diff-icon {
  font-size: 40px;
  margin-bottom: var(--space-md);
}

.diff-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.diff-card p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}

/* --- Brand Collab --- */
.brand-collab {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-3xl) var(--space-lg);
}

.brand-collab h2 {
  font-size: clamp(24px, 3vw, 40px);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-sm);
}

.brand-collab p {
  font-size: 18px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.brand-collab-items {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
}

.brand-collab-item {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-lg);
  text-align: center;
  width: 180px;
}

.brand-collab-item .item-icon { font-size: 48px; margin-bottom: var(--space-sm); }
.brand-collab-item h4 { font-size: 14px; font-weight: 600; }

/* --- Quick Links --- */
.quick-links {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
  padding: var(--space-2xl) var(--space-lg);
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-lg);
  border: 1px solid var(--color-border);
  border-radius: 20px;
  font-size: 14px;
  color: var(--color-primary-hex);
  text-decoration: none;
  transition: all var(--transition-fast);
}

.quick-link:hover {
  background: var(--color-bg-light-hex);
  text-decoration: none;
}

/* --- Category Sticky Nav --- */
.category-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
}

.category-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--space-xl);
  padding: var(--space-sm) var(--space-lg);
  overflow-x: auto;
  scrollbar-width: none;
}

.category-nav-inner::-webkit-scrollbar { display: none; }

.category-nav a {
  font-size: 13px;
  font-weight: 400;
  color: var(--color-secondary-text-hex);
  text-decoration: none;
  white-space: nowrap;
  padding: var(--space-xs) 0;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
}

.category-nav a:hover {
  color: var(--color-primary-hex);
  text-decoration: none;
}

.category-nav a.active {
  color: var(--color-primary-hex);
  border-bottom-color: var(--color-primary-hex);
}

/* --- Shopping Guides --- */
.guide-list {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.guide-item {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
}

.guide-item .guide-icon { font-size: 40px; margin-bottom: var(--space-md); }

.guide-item h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.guide-item p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}

/* --- Ways to Save --- */
.save-list {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-md);
}

.save-item {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
}

.save-item .save-icon { font-size: 36px; margin-bottom: var(--space-md); }

.save-item h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.save-item p {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
}

/* --- Setup Support --- */
.setup-support {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg);
}

.setup-support h3 {
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.setup-support p {
  font-size: 16px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

/* --- Product Experience --- */
.product-experience {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg);
}

.product-experience h3 {
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.product-experience p {
  font-size: 16px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-md);
}

/* --- Special Stores --- */
.special-stores-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--space-md);
}

.special-store-card {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  text-align: center;
  transition: transform var(--transition-med);
}

.special-store-card:hover { transform: translateY(-2px); }

.special-store-card .store-icon { font-size: 36px; margin-bottom: var(--space-md); }

.special-store-card h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.special-store-card p {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
}

/* --- Footer --- */
.site-footer {
  background: var(--color-bg-light-hex);
  padding: var(--space-2xl) var(--space-lg) var(--space-lg);
  border-top: 1px solid var(--color-border);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-legal {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  line-height: 1.6;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-lg);
  border-bottom: 1px solid var(--color-border);
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-2xl);
  margin-bottom: var(--space-2xl);
}

.footer-col h4 {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-primary-hex);
  margin-bottom: var(--space-sm);
  cursor: default;
}

.footer-col ul li {
  margin-bottom: 4px;
}

.footer-col ul li a {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  transition: color var(--transition-fast);
}

.footer-col ul li a:hover {
  color: var(--color-primary-hex);
  text-decoration: none;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-md);
  border-top: 1px solid var(--color-border);
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  flex-wrap: wrap;
  gap: var(--space-sm);
}

/* --- Footer Accordion (Mobile) --- */
@media (max-width: 768px) {
  .footer-columns {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid var(--color-border);
  }

  .footer-col h4 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--space-md) 0;
    cursor: pointer;
    user-select: none;
  }

  .footer-col h4::after {
    content: '+';
    font-size: 16px;
    font-weight: 400;
    transition: transform var(--transition-fast);
  }

  .footer-col.open h4::after {
    content: '−';
  }

  .footer-col ul {
    display: none;
    padding-bottom: var(--space-md);
  }

  .footer-col.open ul {
    display: block;
  }
}

/* --- Responsive --- */
@media (max-width: 768px) {
  .product-grid {
    grid-template-columns: 1fr;
  }

  .product-tile {
    min-height: 340px;
  }

  .global-nav .nav-links {
    gap: var(--space-md);
  }

  .global-nav .nav-links a {
    font-size: 11px;
  }

  .product-bar-inner {
    justify-content: flex-start;
    gap: var(--space-lg);
  }

  .carousel-arrow {
    display: none;
  }

  .carousel-track {
    padding-left: var(--space-md);
    padding-right: var(--space-md);
  }

  .product-card {
    flex: 0 0 240px;
  }

  .help-cards, .diff-cards, .guide-list, .save-list, .special-stores-grid {
    grid-template-columns: 1fr;
  }

  .entertainment-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .brand-collab-items {
    justify-content: flex-start;
    overflow-x: auto;
    flex-wrap: nowrap;
  }

  .quick-links {
    justify-content: flex-start;
    overflow-x: auto;
    flex-wrap: nowrap;
  }
}

@media (max-width: 480px) {
  .entertainment-cards {
    grid-template-columns: 1fr;
  }

  .page-hero {
    padding: var(--space-2xl) var(--space-md) var(--space-xl);
  }

  .section {
    padding: var(--space-2xl) var(--space-md);
  }
}

/* --- Utility --- */
.text-center { text-align: center; }
.mt-lg { margin-top: var(--space-lg); }
.mb-lg { margin-bottom: var(--space-lg); }

/* --- Savings Carousel Cards --- */
.savings-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  transition: transform var(--transition-med);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg) var(--space-lg);
}

.savings-card:hover { transform: translateY(-2px); }

.savings-card .savings-icon {
  font-size: 48px;
  margin-bottom: var(--space-md);
}

.savings-card h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.savings-card p {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  line-height: 1.5;
}

/* --- Experience Section --- */
.experience-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-md);
}

.experience-card {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  text-align: center;
}

.experience-card .exp-icon { font-size: 40px; margin-bottom: var(--space-md); }

.experience-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.experience-card p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}

/* ============================================
   Orchard — Design System & Shared Styles
   ============================================ */

/* --- OKLCH Color Tokens --- */
:root {
  --color-primary: oklch(20% 0.02 265);
  --color-primary-hex: #1d1d1f;
  --color-secondary-text: oklch(52% 0.01 265);
  --color-secondary-text-hex: #6e6e73;
  --color-bg-light: oklch(97% 0.005 265);
  --color-bg-light-hex: #f5f5f7;
  --color-bg-white: #ffffff;
  --color-blue: oklch(50% 0.19 265);
  --color-blue-hex: #0066cc;
  --color-blue-hover: #004499;
  --color-border: #d2d2d7;
  --color-badge: #bf4800;
  --color-tile-bg-1: #fbfbfd;
  --color-tile-bg-2: #f0f0f5;

  /* Typography */
  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 48px;

  /* Cards */
  --card-radius: 18px;
  --card-shadow: 0 2px 12px rgba(0,0,0,0.08);

  /* Carousel */
  --carousel-card-width: 280px;
  --carousel-gap: 16px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-med: 250ms ease;
  --transition-slow: 400ms ease;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-stack);
  color: var(--color-primary-hex);
  background: var(--color-bg-white);
  line-height: 1.5;
  overflow-x: hidden;
}

a { color: var(--color-blue-hex); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--color-blue-hover); text-decoration: underline; }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

ul, ol { list-style: none; }

/* --- Top Navigation (Slim Nav) --- */
.global-nav {
  background: rgba(29,29,31,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--nav-height);
}

.global-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 var(--space-lg);
}

.global-nav .logo {
  color: #f5f5f7;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
}

.global-nav .nav-links {
  display: flex;
  gap: var(--space-xl);
  align-items: center;
}

.global-nav .nav-links a {
  color: rgba(245,245,247,0.85);
  font-size: 12px;
  font-weight: 400;
  text-decoration: none;
  transition: color var(--transition-fast);
  letter-spacing: 0;
}

.global-nav .nav-links a:hover {
  color: #fff;
  text-decoration: none;
}

/* --- Ribbon Banner --- */
.ribbon-banner {
  background: var(--color-bg-light-hex);
  text-align: center;
  padding: var(--space-sm) var(--space-md);
  font-size: 14px;
  color: var(--color-primary-hex);
  border-bottom: 1px solid var(--color-border);
}

.ribbon-banner a {
  color: var(--color-blue-hex);
  white-space: nowrap;
}

/* --- Page Hero --- */
.page-hero {
  text-align: center;
  padding: var(--space-4xl) var(--space-lg) var(--space-2xl);
}

.page-hero h1 {
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.08;
  margin-bottom: var(--space-sm);
}

.page-hero p {
  font-size: clamp(18px, 2.5vw, 24px);
  font-weight: 400;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.hero-ctas {
  display: flex;
  gap: var(--space-lg);
  justify-content: center;
  flex-wrap: wrap;
}

.hero-ctas a {
  font-size: 17px;
  font-weight: 400;
}

/* --- Section --- */
.section {
  padding: var(--space-3xl) var(--space-lg);
}

.section-light {
  background: var(--color-bg-light-hex);
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.section-header h2 {
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: var(--space-sm);
}

.section-header p {
  font-size: clamp(16px, 2vw, 21px);
  color: var(--color-secondary-text-hex);
  font-weight: 400;
}

.section-header .promo {
  font-size: 14px;
  color: var(--color-secondary-text-hex);
  margin-top: var(--space-xs);
}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  gap: var(--carousel-gap);
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: var(--space-sm) 0 var(--space-md);
  scrollbar-width: none;
}

.carousel-track::-webkit-scrollbar { display: none; }

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.85);
  border: 1px solid var(--color-border);
  box-shadow: 0 1px 4px rgba(0,0,0,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: background var(--transition-fast), box-shadow var(--transition-fast);
  cursor: pointer;
}

.carousel-arrow:hover {
  background: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}

.carousel-arrow svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: var(--color-primary-hex);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.carousel-arrow.prev { left: -18px; }
.carousel-arrow.next { right: -18px; }

.carousel-arrow:disabled {
  opacity: 0.3;
  cursor: default;
}

/* --- Product Card (Carousel) --- */
.product-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  transition: transform var(--transition-med), box-shadow var(--transition-med);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 20px rgba(0,0,0,0.12);
}

.product-card .card-img {
  width: 100%;
  height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}

.product-card .card-img .badge {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--color-badge);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.product-card .card-img .product-icon {
  font-size: 72px;
  opacity: 0.9;
}

.product-card .card-body {
  padding: var(--space-md);
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-card .card-body h3 {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
  margin-bottom: 4px;
}

.product-card .card-body .tagline {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-sm);
  line-height: 1.4;
}

.product-card .card-body .price {
  font-size: 14px;
  font-weight: 600;
  margin-top: auto;
}

.product-card .card-body .monthly {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  font-weight: 400;
}

.product-card .card-body .card-links {
  display: flex;
  gap: var(--space-md);
  margin-top: var(--space-sm);
}

.product-card .card-body .card-links a {
  font-size: 13px;
}

.product-card .note {
  font-size: 11px;
  color: var(--color-secondary-text-hex);
  margin-top: 4px;
}

/* Product image placeholder styles */
.img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80px;
}

.img-placeholder.phone { background: linear-gradient(135deg, #e8e8ed 0%, #d2d2d7 100%); }
.img-placeholder.laptop { background: linear-gradient(135deg, #e8edf0 0%, #c8d0d8 100%); }
.img-placeholder.tablet { background: linear-gradient(135deg, #ece8f0 0%, #d8d0e0 100%); }
.img-placeholder.headphones { background: linear-gradient(135deg, #f0ece8 0%, #e0d8d0 100%); }
.img-placeholder.watch { background: linear-gradient(135deg, #e8f0ec 0%, #d0e0d8 100%); }
.img-placeholder.speaker { background: linear-gradient(135deg, #f0f0e8 0%, #e0e0d0 100%); }
.img-placeholder.accessory { background: linear-gradient(135deg, #f5f0f0 0%, #e8e0e0 100%); }
.img-placeholder.earbuds { background: linear-gradient(135deg, #f0e8f0 0%, #e0d8e0 100%); }

/* --- Product Grid (Homepage) --- */
.product-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
  padding: 0 var(--space-lg);
}

.product-tile {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  overflow: hidden;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg) var(--space-lg);
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 400px;
}

.product-tile .tile-img {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 100px;
  margin-bottom: var(--space-lg);
}

.product-tile h3 {
  font-size: clamp(24px, 3vw, 32px);
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: var(--space-xs);
}

.product-tile .tile-tagline {
  font-size: clamp(16px, 2vw, 19px);
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.product-tile .tile-ctas {
  display: flex;
  gap: var(--space-lg);
  justify-content: center;
}

.product-tile .tile-ctas a {
  font-size: 15px;
}

.tile-tradein {
  background: linear-gradient(135deg, #1d1d1f 0%, #3a3a3c 100%);
  color: #f5f5f7;
}

.tile-tradein h3 { color: #f5f5f7; }
.tile-tradein .tile-tagline { color: rgba(245,245,247,0.8); }

/* --- Entertainment Tabs --- */
.entertainment-section {
  max-width: var(--max-width);
  margin: 0 auto;
}

.tab-nav {
  display: flex;
  gap: var(--space-sm);
  justify-content: center;
  margin-bottom: var(--space-2xl);
  flex-wrap: wrap;
}

.tab-nav button {
  padding: var(--space-sm) var(--space-lg);
  font-size: 15px;
  font-weight: 500;
  border-radius: 20px;
  color: var(--color-primary-hex);
  background: var(--color-bg-light-hex);
  transition: all var(--transition-fast);
}

.tab-nav button:hover {
  background: var(--color-border);
}

.tab-nav button.active {
  background: var(--color-primary-hex);
  color: #fff;
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

.entertainment-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-md);
}

.entertainment-card {
  border-radius: var(--card-radius);
  overflow: hidden;
  background: var(--color-bg-white);
  box-shadow: var(--card-shadow);
  transition: transform var(--transition-med);
}

.entertainment-card:hover {
  transform: translateY(-2px);
}

.entertainment-card .card-visual {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 56px;
}

.entertainment-card .card-info {
  padding: var(--space-md);
}

.entertainment-card .card-info h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}

.entertainment-card .card-info .subtitle {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-sm);
}

.entertainment-card .card-info a {
  font-size: 13px;
}

/* --- Product Icon Bar --- */
.product-bar {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: var(--space-lg);
  overflow-x: auto;
  scrollbar-width: none;
}

.product-bar::-webkit-scrollbar { display: none; }

.product-bar-inner {
  display: flex;
  gap: var(--space-xl);
  justify-content: center;
  min-width: max-content;
}

.product-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-xs);
  text-decoration: none;
  color: var(--color-primary-hex);
  transition: color var(--transition-fast);
  flex-shrink: 0;
}

.product-bar-item:hover { color: var(--color-blue-hex); text-decoration: none; }

.product-bar-item .bar-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: var(--color-bg-light-hex);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  transition: background var(--transition-fast);
}

.product-bar-item:hover .bar-icon {
  background: var(--color-border);
}

.product-bar-item span {
  font-size: 11px;
  font-weight: 500;
  text-align: center;
}

/* --- Help Cards --- */
.help-cards {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.help-card {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
  transition: transform var(--transition-med);
}

.help-card:hover { transform: translateY(-2px); }

.help-card .help-icon {
  font-size: 48px;
  margin-bottom: var(--space-md);
}

.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.help-card p {
  font-size: 14px;
  color: var(--color-secondary-text-hex);
  line-height: 1.5;
}

/* --- Difference Cards --- */
.diff-cards {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-md);
}

.diff-card {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
  transition: transform var(--transition-med);
}

.diff-card:hover { transform: translateY(-2px); }

.diff-card .diff-icon {
  font-size: 40px;
  margin-bottom: var(--space-md);
}

.diff-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.diff-card p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}

/* --- Brand Collab --- */
.brand-collab {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-3xl) var(--space-lg);
}

.brand-collab h2 {
  font-size: clamp(24px, 3vw, 40px);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-sm);
}

.brand-collab p {
  font-size: 18px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.brand-collab-items {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
}

.brand-collab-item {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-lg);
  text-align: center;
  width: 180px;
}

.brand-collab-item .item-icon { font-size: 48px; margin-bottom: var(--space-sm); }
.brand-collab-item h4 { font-size: 14px; font-weight: 600; }

/* --- Quick Links --- */
.quick-links {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
  padding: var(--space-2xl) var(--space-lg);
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-lg);
  border: 1px solid var(--color-border);
  border-radius: 20px;
  font-size: 14px;
  color: var(--color-primary-hex);
  text-decoration: none;
  transition: all var(--transition-fast);
}

.quick-link:hover {
  background: var(--color-bg-light-hex);
  text-decoration: none;
}

/* --- Category Sticky Nav --- */
.category-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
}

.category-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--space-xl);
  padding: var(--space-sm) var(--space-lg);
  overflow-x: auto;
  scrollbar-width: none;
}

.category-nav-inner::-webkit-scrollbar { display: none; }

.category-nav a {
  font-size: 13px;
  font-weight: 400;
  color: var(--color-secondary-text-hex);
  text-decoration: none;
  white-space: nowrap;
  padding: var(--space-xs) 0;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
}

.category-nav a:hover {
  color: var(--color-primary-hex);
  text-decoration: none;
}

.category-nav a.active {
  color: var(--color-primary-hex);
  border-bottom-color: var(--color-primary-hex);
}

/* --- Shopping Guides --- */
.guide-list {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.guide-item {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
}

.guide-item .guide-icon { font-size: 40px; margin-bottom: var(--space-md); }

.guide-item h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.guide-item p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}

/* --- Ways to Save --- */
.save-list {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-md);
}

.save-item {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
}

.save-item .save-icon { font-size: 36px; margin-bottom: var(--space-md); }

.save-item h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.save-item p {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
}

/* --- Setup Support --- */
.setup-support {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg);
}

.setup-support h3 {
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.setup-support p {
  font-size: 16px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

/* --- Product Experience --- */
.product-experience {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg);
}

.product-experience h3 {
  font-size: clamp(20px, 2.5vw, 28px);
  font-weight: 700;
  margin-bottom: var(--space-sm);
}

.product-experience p {
  font-size: 16px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-md);
}

/* --- Special Stores --- */
.special-stores-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: var(--space-md);
}

.special-store-card {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  text-align: center;
  transition: transform var(--transition-med);
}

.special-store-card:hover { transform: translateY(-2px); }

.special-store-card .store-icon { font-size: 36px; margin-bottom: var(--space-md); }

.special-store-card h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.special-store-card p {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
}

/* --- Footer --- */
.site-footer {
  background: var(--color-bg-light-hex);
  padding: var(--space-2xl) var(--space-lg) var(--space-lg);
  border-top: 1px solid var(--color-border);
}

.footer-inner {
  max-width: var(--max-width);
  margin: 0 auto;
}

.footer-legal {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  line-height: 1.6;
  margin-bottom: var(--space-lg);
  padding-bottom: var(--space-lg);
  border-bottom: 1px solid var(--color-border);
}

.footer-columns {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(180px, 1fr));
  gap: var(--space-2xl);
  margin-bottom: var(--space-2xl);
}

.footer-col h4 {
  font-size: 12px;
  font-weight: 600;
  color: var(--color-primary-hex);
  margin-bottom: var(--space-sm);
  cursor: default;
}

.footer-col ul li {
  margin-bottom: 4px;
}

.footer-col ul li a {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  transition: color var(--transition-fast);
}

.footer-col ul li a:hover {
  color: var(--color-primary-hex);
  text-decoration: none;
}

.footer-bottom {
  display: flex;
  justify-content: space-between;
  align-items: center;
  padding-top: var(--space-md);
  border-top: 1px solid var(--color-border);
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  flex-wrap: wrap;
  gap: var(--space-sm);
}

/* --- Footer Accordion (Mobile) --- */
@media (max-width: 768px) {
  .footer-columns {
    grid-template-columns: 1fr;
    gap: 0;
  }

  .footer-col {
    border-bottom: 1px solid var(--color-border);
  }

  .footer-col h4 {
    display: flex;
    justify-content: space-between;
    align-items: center;
    padding: var(--space-md) 0;
    cursor: pointer;
    user-select: none;
  }

  .footer-col h4::after {
    content: '+';
    font-size: 16px;
    font-weight: 400;
    transition: transform var(--transition-fast);
  }

  .footer-col.open h4::after {
    content: '−';
  }

  .footer-col ul {
    display: none;
    padding-bottom: var(--space-md);
  }

  .footer-col.open ul {
    display: block;
  }
}

/* --- Responsive --- */
@media (max-width: 768px) {
  .product-grid {
    grid-template-columns: 1fr;
  }

  .product-tile {
    min-height: 340px;
  }

  .global-nav .nav-links {
    gap: var(--space-md);
  }

  .global-nav .nav-links a {
    font-size: 11px;
  }

  .product-bar-inner {
    justify-content: flex-start;
    gap: var(--space-lg);
  }

  .carousel-arrow {
    display: none;
  }

  .carousel-track {
    padding-left: var(--space-md);
    padding-right: var(--space-md);
  }

  .product-card {
    flex: 0 0 240px;
  }

  .help-cards, .diff-cards, .guide-list, .save-list, .special-stores-grid {
    grid-template-columns: 1fr;
  }

  .entertainment-cards {
    grid-template-columns: repeat(2, 1fr);
  }

  .brand-collab-items {
    justify-content: flex-start;
    overflow-x: auto;
    flex-wrap: nowrap;
  }

  .quick-links {
    justify-content: flex-start;
    overflow-x: auto;
    flex-wrap: nowrap;
  }
}

@media (max-width: 480px) {
  .entertainment-cards {
    grid-template-columns: 1fr;
  }

  .page-hero {
    padding: var(--space-2xl) var(--space-md) var(--space-xl);
  }

  .section {
    padding: var(--space-2xl) var(--space-md);
  }
}

/* --- Utility --- */
.text-center { text-align: center; }
.mt-lg { margin-top: var(--space-lg); }
.mb-lg { margin-bottom: var(--space-lg); }

/* --- Savings Carousel Cards --- */
.savings-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  transition: transform var(--transition-med);
  display: flex;
  flex-direction: column;
  align-items: center;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg) var(--space-lg);
}

.savings-card:hover { transform: translateY(-2px); }

.savings-card .savings-icon {
  font-size: 48px;
  margin-bottom: var(--space-md);
}

.savings-card h3 {
  font-size: 15px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.savings-card p {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  line-height: 1.5;
}

/* --- Experience Section --- */
.experience-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-md);
}

.experience-card {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  text-align: center;
}

.experience-card .exp-icon { font-size: 40px; margin-bottom: var(--space-md); }

.experience-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.experience-card p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}

raw_arguments.content:
/* ============================================
   Orchard — Design System & Shared Styles
   ============================================ */

/* --- OKLCH Color Tokens --- */
:root {
  --color-primary: oklch(20% 0.02 265);
  --color-primary-hex: #1d1d1f;
  --color-secondary-text: oklch(52% 0.01 265);
  --color-secondary-text-hex: #6e6e73;
  --color-bg-light: oklch(97% 0.005 265);
  --color-bg-light-hex: #f5f5f7;
  --color-bg-white: #ffffff;
  --color-blue: oklch(50% 0.19 265);
  --color-blue-hex: #0066cc;
  --color-blue-hover: #004499;
  --color-border: #d2d2d7;
  --color-badge: #bf4800;
  --color-tile-bg-1: #fbfbfd;
  --color-tile-bg-2: #f0f0f5;

  /* Typography */
  --font-stack: -apple-system, BlinkMacSystemFont, 'SF Pro Display', 'SF Pro Text', 'Helvetica Neue', Helvetica, Arial, sans-serif;

  /* Spacing */
  --space-xs: 4px;
  --space-sm: 8px;
  --space-md: 16px;
  --space-lg: 24px;
  --space-xl: 32px;
  --space-2xl: 48px;
  --space-3xl: 64px;
  --space-4xl: 96px;

  /* Layout */
  --max-width: 1200px;
  --nav-height: 48px;

  /* Cards */
  --card-radius: 18px;
  --card-shadow: 0 2px 12px rgba(0,0,0,0.08);

  /* Carousel */
  --carousel-card-width: 280px;
  --carousel-gap: 16px;

  /* Transitions */
  --transition-fast: 150ms ease;
  --transition-med: 250ms ease;
  --transition-slow: 400ms ease;
}

/* --- Reset & Base --- */
*, *::before, *::after { box-sizing: border-box; margin: 0; padding: 0; }

html {
  font-size: 16px;
  -webkit-font-smoothing: antialiased;
  -moz-osx-font-smoothing: grayscale;
  scroll-behavior: smooth;
}

body {
  font-family: var(--font-stack);
  color: var(--color-primary-hex);
  background: var(--color-bg-white);
  line-height: 1.5;
  overflow-x: hidden;
}

a { color: var(--color-blue-hex); text-decoration: none; transition: color var(--transition-fast); }
a:hover { color: var(--color-blue-hover); text-decoration: underline; }

img { max-width: 100%; display: block; }

button { font-family: inherit; cursor: pointer; border: none; background: none; }

ul, ol { list-style: none; }

/* --- Top Navigation (Slim Nav) --- */
.global-nav {
  background: rgba(29,29,31,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  position: sticky;
  top: 0;
  z-index: 1000;
  height: var(--nav-height);
}

.global-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  align-items: center;
  justify-content: space-between;
  height: 100%;
  padding: 0 var(--space-lg);
}

.global-nav .logo {
  color: #f5f5f7;
  font-size: 17px;
  font-weight: 600;
  letter-spacing: -0.01em;
  text-decoration: none;
}

.global-nav .nav-links {
  display: flex;
  gap: var(--space-xl);
  align-items: center;
}

.global-nav .nav-links a {
  color: rgba(245,245,247,0.85);
  font-size: 12px;
  font-weight: 400;
  text-decoration: none;
  transition: color var(--transition-fast);
  letter-spacing: 0;
}

.global-nav .nav-links a:hover {
  color: #fff;
  text-decoration: none;
}

/* --- Ribbon Banner --- */
.ribbon-banner {
  background: var(--color-bg-light-hex);
  text-align: center;
  padding: var(--space-sm) var(--space-md);
  font-size: 14px;
  color: var(--color-primary-hex);
  border-bottom: 1px solid var(--color-border);
}

.ribbon-banner a {
  color: var(--color-blue-hex);
  white-space: nowrap;
}

/* --- Page Hero --- */
.page-hero {
  text-align: center;
  padding: var(--space-4xl) var(--space-lg) var(--space-2xl);
}

.page-hero h1 {
  font-size: clamp(32px, 5vw, 56px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.08;
  margin-bottom: var(--space-sm);
}

.page-hero p {
  font-size: clamp(18px, 2.5vw, 24px);
  font-weight: 400;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.hero-ctas {
  display: flex;
  gap: var(--space-lg);
  justify-content: center;
  flex-wrap: wrap;
}

.hero-ctas a {
  font-size: 17px;
  font-weight: 400;
}

/* --- Section --- */
.section {
  padding: var(--space-3xl) var(--space-lg);
}

.section-light {
  background: var(--color-bg-light-hex);
}

.section-header {
  text-align: center;
  margin-bottom: var(--space-2xl);
}

.section-header h2 {
  font-size: clamp(28px, 4vw, 48px);
  font-weight: 700;
  letter-spacing: -0.02em;
  line-height: 1.1;
  margin-bottom: var(--space-sm);
}

.section-header p {
  font-size: clamp(16px, 2vw, 21px);
  color: var(--color-secondary-text-hex);
  font-weight: 400;
}

.section-header .promo {
  font-size: 14px;
  color: var(--color-secondary-text-hex);
  margin-top: var(--space-xs);
}

/* --- Carousel --- */
.carousel-wrapper {
  position: relative;
  max-width: var(--max-width);
  margin: 0 auto;
}

.carousel-track {
  display: flex;
  gap: var(--carousel-gap);
  overflow-x: auto;
  scroll-behavior: smooth;
  scroll-snap-type: x mandatory;
  -webkit-overflow-scrolling: touch;
  padding: var(--space-sm) 0 var(--space-md);
  scrollbar-width: none;
}

.carousel-track::-webkit-scrollbar { display: none; }

.carousel-arrow {
  position: absolute;
  top: 50%;
  transform: translateY(-50%);
  width: 36px;
  height: 36px;
  border-radius: 50%;
  background: rgba(255,255,255,0.85);
  border: 1px solid var(--color-border);
  box-shadow: 0 1px 4px rgba(0,0,0,0.1);
  display: flex;
  align-items: center;
  justify-content: center;
  z-index: 10;
  transition: background var(--transition-fast), box-shadow var(--transition-fast);
  cursor: pointer;
}

.carousel-arrow:hover {
  background: #fff;
  box-shadow: 0 2px 8px rgba(0,0,0,0.15);
}

.carousel-arrow svg {
  width: 16px;
  height: 16px;
  fill: none;
  stroke: var(--color-primary-hex);
  stroke-width: 2.5;
  stroke-linecap: round;
  stroke-linejoin: round;
}

.carousel-arrow.prev { left: -18px; }
.carousel-arrow.next { right: -18px; }

.carousel-arrow:disabled {
  opacity: 0.3;
  cursor: default;
}

/* --- Product Card (Carousel) --- */
.product-card {
  flex: 0 0 var(--carousel-card-width);
  scroll-snap-align: start;
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  overflow: hidden;
  box-shadow: var(--card-shadow);
  transition: transform var(--transition-med), box-shadow var(--transition-med);
  display: flex;
  flex-direction: column;
}

.product-card:hover {
  transform: translateY(-2px);
  box-shadow: 0 4px 20px rgba(0,0,0,0.12);
}

.product-card .card-img {
  width: 100%;
  height: 220px;
  display: flex;
  align-items: center;
  justify-content: center;
  overflow: hidden;
  position: relative;
}

.product-card .card-img .badge {
  position: absolute;
  top: var(--space-sm);
  left: var(--space-sm);
  background: var(--color-badge);
  color: #fff;
  font-size: 11px;
  font-weight: 600;
  padding: 2px 8px;
  border-radius: 4px;
  text-transform: uppercase;
  letter-spacing: 0.02em;
}

.product-card .card-img .product-icon {
  font-size: 72px;
  opacity: 0.9;
}

.product-card .card-body {
  padding: var(--space-md);
  flex: 1;
  display: flex;
  flex-direction: column;
}

.product-card .card-body h3 {
  font-size: 16px;
  font-weight: 600;
  line-height: 1.3;
  margin-bottom: 4px;
}

.product-card .card-body .tagline {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-sm);
  line-height: 1.4;
}

.product-card .card-body .price {
  font-size: 14px;
  font-weight: 600;
  margin-top: auto;
}

.product-card .card-body .monthly {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  font-weight: 400;
}

.product-card .card-body .card-links {
  display: flex;
  gap: var(--space-md);
  margin-top: var(--space-sm);
}

.product-card .card-body .card-links a {
  font-size: 13px;
}

.product-card .note {
  font-size: 11px;
  color: var(--color-secondary-text-hex);
  margin-top: 4px;
}

/* Product image placeholder styles */
.img-placeholder {
  width: 100%;
  height: 100%;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 80px;
}

.img-placeholder.phone { background: linear-gradient(135deg, #e8e8ed 0%, #d2d2d7 100%); }
.img-placeholder.laptop { background: linear-gradient(135deg, #e8edf0 0%, #c8d0d8 100%); }
.img-placeholder.tablet { background: linear-gradient(135deg, #ece8f0 0%, #d8d0e0 100%); }
.img-placeholder.headphones { background: linear-gradient(135deg, #f0ece8 0%, #e0d8d0 100%); }
.img-placeholder.watch { background: linear-gradient(135deg, #e8f0ec 0%, #d0e0d8 100%); }
.img-placeholder.speaker { background: linear-gradient(135deg, #f0f0e8 0%, #e0e0d0 100%); }
.img-placeholder.accessory { background: linear-gradient(135deg, #f5f0f0 0%, #e8e0e0 100%); }
.img-placeholder.earbuds { background: linear-gradient(135deg, #f0e8f0 0%, #e0d8e0 100%); }

/* --- Product Grid (Homepage) --- */
.product-grid {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(2, 1fr);
  gap: var(--space-md);
  padding: 0 var(--space-lg);
}

.product-tile {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  overflow: hidden;
  text-align: center;
  padding: var(--space-2xl) var(--space-lg) var(--space-lg);
  position: relative;
  display: flex;
  flex-direction: column;
  align-items: center;
  min-height: 400px;
}

.product-tile .tile-img {
  height: 200px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 100px;
  margin-bottom: var(--space-lg);
}

.product-tile h3 {
  font-size: clamp(24px, 3vw, 32px);
  font-weight: 700;
  letter-spacing: -0.01em;
  margin-bottom: var(--space-xs);
}

.product-tile .tile-tagline {
  font-size: clamp(16px, 2vw, 19px);
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.product-tile .tile-ctas {
  display: flex;
  gap: var(--space-lg);
  justify-content: center;
}

.product-tile .tile-ctas a {
  font-size: 15px;
}

.tile-tradein {
  background: linear-gradient(135deg, #1d1d1f 0%, #3a3a3c 100%);
  color: #f5f5f7;
}

.tile-tradein h3 { color: #f5f5f7; }
.tile-tradein .tile-tagline { color: rgba(245,245,247,0.8); }

/* --- Entertainment Tabs --- */
.entertainment-section {
  max-width: var(--max-width);
  margin: 0 auto;
}

.tab-nav {
  display: flex;
  gap: var(--space-sm);
  justify-content: center;
  margin-bottom: var(--space-2xl);
  flex-wrap: wrap;
}

.tab-nav button {
  padding: var(--space-sm) var(--space-lg);
  font-size: 15px;
  font-weight: 500;
  border-radius: 20px;
  color: var(--color-primary-hex);
  background: var(--color-bg-light-hex);
  transition: all var(--transition-fast);
}

.tab-nav button:hover {
  background: var(--color-border);
}

.tab-nav button.active {
  background: var(--color-primary-hex);
  color: #fff;
}

.tab-content {
  display: none;
}

.tab-content.active {
  display: block;
}

.entertainment-cards {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(220px, 1fr));
  gap: var(--space-md);
}

.entertainment-card {
  border-radius: var(--card-radius);
  overflow: hidden;
  background: var(--color-bg-white);
  box-shadow: var(--card-shadow);
  transition: transform var(--transition-med);
}

.entertainment-card:hover {
  transform: translateY(-2px);
}

.entertainment-card .card-visual {
  height: 160px;
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 56px;
}

.entertainment-card .card-info {
  padding: var(--space-md);
}

.entertainment-card .card-info h4 {
  font-size: 14px;
  font-weight: 600;
  margin-bottom: 2px;
}

.entertainment-card .card-info .subtitle {
  font-size: 12px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-sm);
}

.entertainment-card .card-info a {
  font-size: 13px;
}

/* --- Product Icon Bar --- */
.product-bar {
  max-width: var(--max-width);
  margin: 0 auto;
  padding: var(--space-lg);
  overflow-x: auto;
  scrollbar-width: none;
}

.product-bar::-webkit-scrollbar { display: none; }

.product-bar-inner {
  display: flex;
  gap: var(--space-xl);
  justify-content: center;
  min-width: max-content;
}

.product-bar-item {
  display: flex;
  flex-direction: column;
  align-items: center;
  gap: var(--space-xs);
  text-decoration: none;
  color: var(--color-primary-hex);
  transition: color var(--transition-fast);
  flex-shrink: 0;
}

.product-bar-item:hover { color: var(--color-blue-hex); text-decoration: none; }

.product-bar-item .bar-icon {
  width: 56px;
  height: 56px;
  border-radius: 14px;
  background: var(--color-bg-light-hex);
  display: flex;
  align-items: center;
  justify-content: center;
  font-size: 28px;
  transition: background var(--transition-fast);
}

.product-bar-item:hover .bar-icon {
  background: var(--color-border);
}

.product-bar-item span {
  font-size: 11px;
  font-weight: 500;
  text-align: center;
}

/* --- Help Cards --- */
.help-cards {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.help-card {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
  transition: transform var(--transition-med);
}

.help-card:hover { transform: translateY(-2px); }

.help-card .help-icon {
  font-size: 48px;
  margin-bottom: var(--space-md);
}

.help-card h3 {
  font-size: 17px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.help-card p {
  font-size: 14px;
  color: var(--color-secondary-text-hex);
  line-height: 1.5;
}

/* --- Difference Cards --- */
.diff-cards {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(260px, 1fr));
  gap: var(--space-md);
}

.diff-card {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
  padding: var(--space-2xl) var(--space-lg);
  box-shadow: var(--card-shadow);
  text-align: center;
  transition: transform var(--transition-med);
}

.diff-card:hover { transform: translateY(-2px); }

.diff-card .diff-icon {
  font-size: 40px;
  margin-bottom: var(--space-md);
}

.diff-card h3 {
  font-size: 16px;
  font-weight: 600;
  margin-bottom: var(--space-xs);
}

.diff-card p {
  font-size: 13px;
  color: var(--color-secondary-text-hex);
}

/* --- Brand Collab --- */
.brand-collab {
  max-width: var(--max-width);
  margin: 0 auto;
  text-align: center;
  padding: var(--space-3xl) var(--space-lg);
}

.brand-collab h2 {
  font-size: clamp(24px, 3vw, 40px);
  font-weight: 700;
  letter-spacing: -0.02em;
  margin-bottom: var(--space-sm);
}

.brand-collab p {
  font-size: 18px;
  color: var(--color-secondary-text-hex);
  margin-bottom: var(--space-lg);
}

.brand-collab-items {
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
}

.brand-collab-item {
  background: var(--color-bg-light-hex);
  border-radius: var(--card-radius);
  padding: var(--space-lg);
  text-align: center;
  width: 180px;
}

.brand-collab-item .item-icon { font-size: 48px; margin-bottom: var(--space-sm); }
.brand-collab-item h4 { font-size: 14px; font-weight: 600; }

/* --- Quick Links --- */
.quick-links {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--space-md);
  justify-content: center;
  flex-wrap: wrap;
  padding: var(--space-2xl) var(--space-lg);
}

.quick-link {
  display: inline-flex;
  align-items: center;
  gap: var(--space-xs);
  padding: var(--space-sm) var(--space-lg);
  border: 1px solid var(--color-border);
  border-radius: 20px;
  font-size: 14px;
  color: var(--color-primary-hex);
  text-decoration: none;
  transition: all var(--transition-fast);
}

.quick-link:hover {
  background: var(--color-bg-light-hex);
  text-decoration: none;
}

/* --- Category Sticky Nav --- */
.category-nav {
  position: sticky;
  top: var(--nav-height);
  z-index: 100;
  background: rgba(255,255,255,0.92);
  backdrop-filter: saturate(180%) blur(20px);
  -webkit-backdrop-filter: saturate(180%) blur(20px);
  border-bottom: 1px solid var(--color-border);
}

.category-nav-inner {
  max-width: var(--max-width);
  margin: 0 auto;
  display: flex;
  gap: var(--space-xl);
  padding: var(--space-sm) var(--space-lg);
  overflow-x: auto;
  scrollbar-width: none;
}

.category-nav-inner::-webkit-scrollbar { display: none; }

.category-nav a {
  font-size: 13px;
  font-weight: 400;
  color: var(--color-secondary-text-hex);
  text-decoration: none;
  white-space: nowrap;
  padding: var(--space-xs) 0;
  border-bottom: 2px solid transparent;
  transition: all var(--transition-fast);
}

.category-nav a:hover {
  color: var(--color-primary-hex);
  text-decoration: none;
}

.category-nav a.active {
  color: var(--color-primary-hex);
  border-bottom-color: var(--color-primary-hex);
}

/* --- Shopping Guides --- */
.guide-list {
  max-width: var(--max-width);
  margin: 0 auto;
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(280px, 1fr));
  gap: var(--space-md);
}

.guide-item {
  background: var(--color-bg-white);
  border-radius: var(--card-radius);
